using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidResearchComparisonCardFileStore{private readonly string _path;public AndroidResearchComparisonCardFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(AndroidResearchComparisonCard value){if(value.DeclaresWinner)throw new InvalidOperationException("Research comparison card cannot declare a winner.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public AndroidResearchComparisonCard Load(){var v=JsonSerializer.Deserialize<AndroidResearchComparisonCard>(File.ReadAllText(_path))??throw new InvalidOperationException("Comparison card JSON is invalid.");if(v.DeclaresWinner)throw new InvalidOperationException("Persisted comparison card declares a winner.");return v;}}
